pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;
    function setUp() public { c = new TimelockController(0, new address[](0), new address[](0)); }
    function testFuzz_property(bytes32 role, address caller) public {
        vm.assume(caller != address(0));
        vm.assume(role != bytes32(0));
        vm.startPrank(caller);
        try c.renounceRole(role, caller) {} catch { vm.stopPrank(); return; }
        vm.stopPrank();
        assertTrue(!c.hasRole(role, caller));
    }
}
